<nav class="working-tabs" aria-label="Show record sections"><?php foreach (['overview'=>'Overview','orders'=>'Shop Orders','revisions'=>'Revisions','pulls'=>'Pulls','returns'=>'Returns','repairs'=>'Repairs','files'=>'Files','history'=>'History','timeline'=>'Timeline','notes'=>'Notes'] as $key=>$label): ?><a href="/shows/<?= e($show['id']) ?>/<?= e($key) ?>" data-workspace data-working-key="<?= e($key) ?>" class="<?= $tab===$key?'active':'' ?>" <?= $tab===$key?'aria-current="page"':'' ?>><?= e($label) ?></a><?php endforeach; ?></nav>
<?php if ($tab==='overview'): ?><div class="dashboard-grid"><section class="card floating-card" data-card-key="show-team"><h2 class="floating-label"><span class="material-symbols-rounded" aria-hidden="true">groups</span>Production team</h2><div class="card-body"><?php foreach (App\Services\Shows::CONTACTS as $field): ?><div class="record-row"><div><small><?= e(ucwords(str_replace('_',' ',$field))) ?></small><strong><?= e($show[$field] ?: 'Not assigned') ?></strong><small><?= e($show[$field . '_email']) ?> <?= e($show[$field . '_phone']) ?></small></div></div><?php endforeach; ?></div></section>
<section class="card floating-card" data-card-key="show-dates"><h2 class="floating-label"><span class="material-symbols-rounded" aria-hidden="true">calendar_month</span>Show milestones</h2><div class="card-body"><?php foreach (App\Services\Shows::DATES as $field): ?><div class="record-row"><strong><?= e(ucwords(str_replace('_',' ',$field))) ?></strong><span><?= e($show[$field]) ?></span></div><?php endforeach; ?></div></section></div>
<?php elseif ($tab==='timeline'): ?><section class="card floating-card" data-card-key="show-timeline"><h2 class="floating-label">Show planning</h2><div class="card-body"><p>Inspect serialized asset assignments, revisions, transfers, returns, and repair windows.</p><a href="/reports/timeline?show=<?= e($show['id']) ?>" data-workspace class="btn btn-primary">Open this show's timeline</a></div></section>
<?php else: ?><div class="section-actions">
<?php if (in_array($tab,['orders','revisions'],true) && P::allows('orders.edit')): ?><a class="btn btn-primary" href="/shows/<?= e($show['id']) ?>/orders/add" data-workspace>Add shop order</a><?php endif; ?>
<?php if ($tab==='returns' && P::allows('returns.edit')): ?><a class="btn btn-primary" href="/shows/<?= e($show['id']) ?>/return" data-workspace>Start returns</a><?php endif; ?>
<?php if (in_array($tab,['pulls','returns'],true) && P::allows('transfers.edit')): ?><a class="btn" href="/shows/<?= e($show['id']) ?>/transfer" data-workspace>Transfer to another show</a><?php endif; ?></div>
<?php if ($tab==='notes' && P::allows('shows.edit') && !in_array($show['status'],['Completed','Archived'],true)): ?><section class="card floating-card" data-card-key="add-note"><h2 class="floating-label">Add a note</h2><div class="card-body"><form action="/shows/<?= e($show['id']) ?>/notes" method="post" data-ajax-form><?= csrf() ?><label class="form-label">Shop note<textarea class="form-control mb-3" name="body" maxlength="10000" required rows="3"></textarea></label><div class="form-error" role="alert" hidden></div><button class="btn btn-primary">Add note</button></form></div></section><?php endif; ?>
<?php if ($tab==='files' && P::allows('shows.edit') && !in_array($show['status'],['Completed','Archived'],true)): ?><section class="card floating-card" data-card-key="add-file"><h2 class="floating-label">Attach show file</h2><div class="card-body"><form action="/shows/<?= e($show['id']) ?>/files" method="post" enctype="multipart/form-data" data-ajax-form><?= csrf() ?><label class="form-label">PDF, image, CSV or text file (10 MB maximum)<input class="form-control mb-3" type="file" name="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,.csv" required></label><div class="form-error" role="alert" hidden></div><button class="btn btn-primary">Upload file</button></form></div></section><?php endif; ?>
